import {createRequire}from'node:module';import{readFile,writeFile}from'node:fs/promises';import{browserExecutable}from'../landmark-preflight/browser-runtime.mjs';
const root=new URL('../../../',import.meta.url),require=createRequire(new URL('3d-viewer/city/package.json',root)),{chromium}=require('playwright'),out=new URL('docs/astra-city/residual-support-review/capitol/framing/',root),report=JSON.parse(await readFile(new URL('report.json',out),'utf8')),browser=await chromium.launch({headless:true,executablePath:browserExecutable(chromium)}),escape=s=>s.replaceAll('&','&amp;').replaceAll('<','&lt;');
try{const page=await browser.newPage({viewport:{width:1500,height:1380}});for(const mode of ['scene','isolated'])for(let n=0;n<report.rows.length;n+=6){const rows=report.rows.slice(n,n+6),cards=rows.map(r=>{const v=r.views.find(v=>v.mode===mode)||r.previousViews?.find(v=>v.mode===mode);return`<figure>${v?`<img src="${v.file}">`:'Missing capture'}<figcaption>${escape(r.name)} · ${r.uid}<br>${mode} · ${v?.active&&v?.final.clear?'native camera clear':'framing / native activation held'} · ${v?.final.targetRays}/${v?.final.totalRays} source rays</figcaption></figure>`;});const path=new URL(`contact-${mode}-${n}.html`,out);await writeFile(path,`<!doctype html><meta charset="utf-8"><style>body{margin:15px;background:#edf0e7;font:16px system-ui;color:#183a32}h1{font-size:22px}main{display:grid;grid-template-columns:1fr 1fr;gap:10px}figure{margin:0;background:white}img{width:100%;height:375px;object-fit:contain}figcaption{padding:6px}</style><h1>${mode.toUpperCase()} · ${n+1}–${n+rows.length} · source components, not complete landmarks</h1><main>${cards.join('')}</main>`);await page.goto(path.href);await page.waitForFunction(()=>[...document.images].every(i=>i.complete&&i.naturalWidth));await page.screenshot({path:new URL(`contact-${mode}-${n}.jpg`,out).pathname,type:'jpeg',quality:87});}}finally{await browser.close();}
